window.AUTH=window.AUTH||{};window.AUTH["23-108"]={"d":"23-108","id":"2023/23-108","n":"Snyder v. United States","briefs":[{"k":"petitioner","label":"Brief of petitioner James E. Snyder","date":"2024-02-05","url":"https://www.supremecourt.gov/DocketPDF/23/23-108/299751/20240205125508613_Snyder%20Brief%20for%20Petitioner.pdf","side":"pet","n":71},{"k":"respondent","label":"Brief of respondent United States","date":"2024-03-11","url":"https://www.supremecourt.gov/DocketPDF/23/23-108/302853/20240311193806471_23-108bsUnitedStates.pdf","side":"res","n":82},{"k":"reply","label":"Reply of petitioner James E. Snyder","date":"2024-04-02","url":"https://www.supremecourt.gov/DocketPDF/23/23-108/306485/20240402120917827_Snyder%20Reply%20Brief.pdf","side":"pet","n":44}],"opinion":"https://www.supremecourt.gov/opinions/23pdf/603us1r48_g3ci.pdf","tr":true,"items":[{"t":"case","label":"Arthur Andersen LLP v. United States","cite":"544 U.S. 696","y":2005,"id":"2004/04-368","sc":1,"by":{"0":"25","1":"39","2":"8"},"q":[{"src":"brief","b":1,"text":"normally associated with wrongful, immoral, depraved, or evil","cite":"544 U.S. 696, 705"},{"src":"argument","who":"Justice Gorsuch","text":"-- and -- and the mens rea that you think it should import here, putting aside the jury instructions and the debate over forfeiture. You mentioned consciousness of wrongdoing, which the Court mentioned also in Arthur Andersen if I recall."},{"src":"argument","who":"Ms. Blatt","text":"I think, when you have Arthur Andersen, official proceedings, document destruction, what have you, \"corruptly\" can mean all kinds of things."},{"src":"argument","who":"Ms. Sinzdak","text":"So I think Arthur Andersen decide -- described \"corruptly.\" It said it has to be corrupt, so that means wrongful or evil or immoral. And there has --"}]},{"t":"case","label":"Atl. Richfield Co. v. Christian","cite":"140 S. Ct. 1335","y":2020,"id":"2019/17-1498","sc":1,"by":{"0":"21"}},{"t":"case","label":"Bartenwerfer v. Buckley","cite":"598 U.S. 69","y":2023,"id":"2022/21-908","sc":1,"by":{"0":"34"}},{"t":"case","label":"Bond v. United States","cite":"572 U.S. 844","y":2014,"id":"2013/12-158","sc":1,"by":{"0":"46"}},{"t":"case","label":"Burgess v. United States","cite":"553 U.S. 124","y":2008,"id":"2007/06-11429","sc":1,"by":{"0":"35"}},{"t":"case","label":"Ciminelli v. United States","cite":"598 U.S. 306","y":2023,"id":"2022/21-1170","sc":1,"by":{"0":"25","2":"23"}},{"t":"case","label":"Citizens United v. FEC","cite":"558 U.S. 310","y":2010,"id":"2008/08-205","sc":1,"by":{"0":"48","2":"21"},"q":[{"src":"brief","b":2,"text":"important governmental interest in preventing … quid pro quo corruption","cite":"558 U.S. 310, 359"}]},{"t":"case","label":"Commonwealth v. Lapham","cite":"31 N.E. 638","y":1892,"court":"Mass.","url":"https://www.courtlistener.com/c/N.E./31/638/","by":{"0":"24"}},{"t":"case","label":"Crandon v. United States","cite":"494 U.S. 152","y":1990,"id":"1989/88-931","sc":1,"by":{"0":"31","1":"7"}},{"t":"case","label":"Dickinson v. Van De Carr","cite":"87 A.D. 386","y":1903,"court":"N.Y. App. Div.","url":"https://www.courtlistener.com/c/A.D./87/386/","by":{"0":"18"},"q":[{"src":"brief","b":0,"text":"variously defined as taking or offering an ‘undue reward’ or ‘reward’ to influence official action.","cite":"87 A.D. 386, 389"}]},{"t":"case","label":"Dubin v. United States","cite":"599 U.S. 110","y":2023,"id":"2022/22-10","sc":1,"by":{"0":"26, 36, 40","2":"10, 15"},"q":[{"src":"brief","b":0,"text":"[T]he staggering breadth of the Government’s reading","cite":"599 U.S. at 129"},{"src":"brief","b":0,"text":"require[s] an individual to act ‘corruptly.’","cite":"599 U.S. at 130"},{"src":"brief","b":2,"text":"the unenviable role of pithily summarizing a list of ‘complicated and prolific’ provisions.","cite":"599 U.S. 110, 121"},{"src":"brief","b":2,"text":"avoid[s] reading incongruous breadth into opaque language.","cite":"599 U.S. at 130"}]},{"t":"case","label":"Epic Sys. Corp. v. Lewis","cite":"584 U.S. 497","y":2018,"id":"2017/16-285","sc":1,"by":{"0":"28, 35"},"q":[{"src":"brief","b":0,"text":"But legislative history is not the law.","cite":"584 U.S. at 523"}]},{"t":"case","label":"Fischer v. United States","cite":"529 U.S. 667","y":2000,"id":"1999/99-116","sc":1,"by":{"0":"37, 49","1":"40","2":"4"},"q":[{"src":"brief","b":0,"text":"expansive construction of § 666[] is … inconsistent with the rule of lenity.","cite":"529 U.S. at 691"},{"src":"opinion","who":"Justice Jackson, dissenting","text":"to ensure the integrity of organizations participating in federal assistance programs.","cite":"529 U. S., at 678"},{"src":"argument","who":"Ms. Blatt","text":"You held in Fischer that it covers Medicare, which is one of the largest industries in this country. It covers every nurse, doctor, orderly, anyone in the hospital."}]},{"t":"case","label":"Gonzaga Univ. v. Doe","cite":"536 U.S. 273","y":2002,"id":"2001/01-679","sc":1,"by":{"0":"47"}},{"t":"case","label":"Jones v. United States","cite":"529 U.S. 848","y":2000,"id":"1999/99-5739","sc":1,"by":{"0":"46"}},{"t":"case","label":"Kelly v. United States","cite":"140 S. Ct. 1565","y":2020,"id":"2019/18-1059","sc":1,"by":{"0":"42"},"q":[{"src":"brief","b":0,"text":"use the criminal law to enforce (its view of) integrity in broad swaths of state and local policymaking.","cite":"140 S. Ct. 1565, 1574"}]},{"t":"case","label":"Marinello v. United States","cite":"138 S. Ct. 1101","y":2018,"id":"2017/16-1144","sc":1,"by":{"0":"40","2":"17"},"q":[{"src":"brief","b":0,"text":"it would have spoken with more clarity.","cite":"138 S. Ct. at 1108"},{"src":"brief","b":0,"text":"to rely upon prosecutorial discretion to narrow the otherwise wide-ranging scope of a criminal statute’s highly abstract general statutory language places great power in the hands of the prosecutor.","cite":"138 S. Ct. at 1108"}]},{"t":"case","label":"Marx v. Gen. Rev. Corp.","cite":"568 U.S. 371","y":2013,"id":"2012/11-1175","sc":1,"by":{"0":"28","2":"10"}},{"t":"case","label":"McCormick v. United States","cite":"500 U.S. 257","y":1991,"id":"1990/89-1918","sc":1,"by":{"0":"48","1":"33","2":"21"},"q":[{"src":"brief","b":0,"text":"Money is constantly being solicited on behalf of candidates … who claim support on the basis of their views and what they intend to do or have done.","cite":"500 U.S. 257, 272"},{"src":"brief","b":1,"text":"the payments are made in return for an explicit promise or undertaking by the official to perform or not to perform an official act.","cite":"500 U.S. 257, 273"},{"src":"argument","who":"Ms. Sinzdak","text":"Under McCormick, there needs to be a quid pro quo in the campaign context, so -- pardon me -- in the campaign contribution context. So the government does not prosecute where there is --"},{"src":"argument","who":"Ms. Sinzdak","text":"That's -- that's all -- well, and pardon me, and then the First Amendment protection that says that under McCormick we understand that to mean that there really has to be an express quid pro quo when we're dealing with a bona fide campaign contribution."}]},{"t":"case","label":"McCutcheon v. FEC","cite":"572 U.S. 185","y":2014,"id":"2013/12-536","sc":1,"by":{"0":"48"}},{"t":"case","label":"McDonnell v. United States","cite":"579 U.S. 550","y":2016,"id":"2015/15-474","sc":1,"by":{"0":"38-40, 43, 45, 49","1":"21, 24, 25, 34","2":"6, 18, 22"},"q":[{"src":"brief","b":0,"text":"construe a criminal statute on the assumption that the Government will use it responsibly.","cite":"579 U.S. at 576"},{"src":"brief","b":0,"text":"State defines itself as a sovereign.","cite":"579 U.S. at 576"},{"src":"brief","b":2,"text":"in fact intend to perform the ‘official act,’ so long as [they] agree[] to do so.","cite":"579 U.S. 550, 572"},{"src":"brief","b":2,"text":"construe a criminal statute on the assumption that the Government will use it responsibly.","cite":"579 U.S. at 576"},{"src":"opinion","who":"Opinion of the Court (Justice Kavanaugh)","text":"defnes itself as a sovereign through the structure of its government, and the character of those who exercise government authority.","cite":"579 U. S. 550, 576"},{"src":"opinion","who":"Opinion of the Court (Justice Kavanaugh)","text":"cannot construe a criminal statute on the assumption that the Government will use it responsibly.","cite":"579 U. S., at 576"},{"src":"opinion","who":"Opinion of the Court (Justice Kavanaugh)","text":"Federal Government in setting standards of good government for local and state offcials.","cite":"579 U. S., at 577"},{"src":"argument","who":"Ms. Blatt","text":"The Court in McDonnell had said you can actually be convicted if you don't have any intent to be influenced under bribery. But, under this statute, 666, the government has --"},{"src":"argument","who":"Justice Sotomayor","text":"They didn't have McDonnell in front of them, so I don't know what that has to do with anything."}]},{"t":"case","label":"Morissette v. United States","cite":"342 U.S. 246","y":1952,"id":"scdb/1951-028","sc":1,"by":{"0":"21"}},{"t":"case","label":"New York v. United States","cite":"505 U.S. 144","y":1992,"id":"1991/91-543","sc":1,"by":{"0":"47"}},{"t":"case","label":"Pennhurst State Sch. & Hosp. v. Halderman","cite":"451 U.S. 1","y":1981,"id":"1980/79-1404","sc":1,"by":{"0":"46-47"},"q":[{"src":"brief","b":0,"text":"rests on whether the State voluntarily and knowingly accepts [Congress’] terms.","cite":"451 U.S. 1, 17"}]},{"t":"case","label":"People v. Johnston","cite":"43 N.W.2d 334","y":1950,"court":"Mich.","url":"https://www.courtlistener.com/c/N.W.2d/43/334/","by":{"0":"24"}},{"t":"case","label":"People v. Seeley","cite":"69 P. 693","y":1902,"court":"Cal.","url":"https://www.courtlistener.com/c/P./69/693/","by":{"0":"24"},"q":[{"src":"brief","b":0,"text":"corruptly agree[] to receive [money] for the purpose of influencing his vote.","cite":"69 P. 693, 694"}]},{"t":"case","label":"Percoco v. United States","cite":"598 U.S. 319","y":2023,"id":"2022/21-1158","sc":1,"by":{"0":"25","2":"23"},"q":[{"src":"brief","b":0,"text":"differ[] substantially from the jury instructions.","cite":"598 U.S. 319, 332"}]},{"t":"case","label":"Perrin v. United States","cite":"444 U.S. 37","y":1979,"id":"1979/78-959","sc":1,"by":{"0":"18"}},{"t":"case","label":"Peter v. Nantkwest, Inc.","cite":"140 S. Ct. 365","y":2019,"id":"2019/18-801","sc":1,"by":{"0":"18"}},{"t":"case","label":"Ratzlaf v. United States","cite":"510 U.S. 135","y":1994,"id":"1993/92-1196","sc":1,"by":{"0":"23"}},{"t":"case","label":"Sabri v. United States","cite":"541 U.S. 600","y":2004,"id":"2003/03-44","sc":1,"by":{"0":"47-48","1":"3, 26-28, 32, 35","2":"4, 19"},"q":[{"src":"brief","b":0,"text":"bribed officials are untrustworthy stewards of federal funds.","cite":"541 U.S. at 606"},{"src":"brief","b":1,"text":"are in fact spent for the general welfare, and not frittered away in graft or on projects undermined when funds are siphoned off or corrupt public officers are derelict about demanding value for dollars.","cite":"541 U.S. 600, 605"},{"src":"brief","b":1,"text":"Congress was within its prerogative to protect spending objects from the menace of local administrators on the take,","cite":"541 U.S. 600, 608"},{"src":"opinion","who":"Justice Jackson, dissenting","text":"to express [a] view as to [§ 666's] soundness as a policy matter.","cite":"541 U. S., at 608"},{"src":"opinion","who":"Justice Jackson, dissenting","text":"addres[s] a legitimate federal concern by licensing federal prosecution in an area historically of state concern.","cite":"541 U. S., at 608"},{"src":"argument","who":"Justice Gorsuch","text":"I know we discussed this in Sabri, but I'm just curious, your thoughts on, I guess, what Justice Alito framed as the first question. What are the limits to what Congress can do to federalize state substantive criminal law here?"},{"src":"argument","who":"Ms. Blatt","text":"So Sabri is definitely in the context of bribery, and so the question would be if the section -- sorry -- the 1984 version just criminalized gratuities and said for or because of official act 10-year penalty, and you would have to -- that -- there, you would meet, I think, the Spending Clause clear statement and the clear statement under Bass to upset the federal/state balance, and you have a pure Sabri question."},{"src":"argument","who":"Justice Gorsuch","text":"In Sabri."}]},{"t":"case","label":"Sackett v. EPA","cite":"598 U.S. 651","y":2023,"id":"2022/21-454","sc":1,"by":{"0":"27"}},{"t":"case","label":"Salinas v. United States","cite":"522 U.S. 52","y":1997,"id":"1997/96-738","sc":1,"by":{"0":"47","1":"27, 28","2":"5"},"q":[{"src":"opinion","who":"Justice Jackson, dissenting","text":"whether state and local employees could be considered `public offcials'","cite":"522 U. S., at 58"}]},{"t":"case","label":"Skilling v. United States","cite":"561 U.S. 358","y":2010,"id":"2009/08-1394","sc":1,"by":{"0":"40","1":"34"}},{"t":"case","label":"State v. Ellis","cite":"33 N.J.L. 102","y":1868,"court":"N.J. Sup. Ct.","url":"https://www.courtlistener.com/c/N.J.L./33/102/","by":{"0":"18"},"q":[{"src":"brief","b":0,"text":"complete when an offer of reward is made to influence the vote or action of the official.","cite":"33 N.J.L. 102, 105"}]},{"t":"case","label":"State v. Milbrath","cite":"527 So. 2d 864","y":1988,"court":"Fla. Dist. Ct. App.","url":"https://www.courtlistener.com/c/So.%202d/527/864/","by":{"0":"24"}},{"t":"case","label":"Sw. Airlines Co. v. Saxon","cite":"596 U.S. 450","y":2022,"url":"https://supreme.justia.com/cases/federal/us/596/450/","sc":1,"by":{"0":"26"},"q":[{"src":"brief","b":0,"text":"must be read and interpreted in their context.","cite":"596 U.S. 450, 455"}]},{"t":"case","label":"United States v. Alfisi","cite":"308 F.3d 144","y":2002,"court":"2d Cir.","url":"https://www.courtlistener.com/c/F.3d/308/144/","by":{"0":"24"}},{"t":"case","label":"United States v. Bass","cite":"404 U.S. 336","y":1971,"id":"1971/70-71","sc":1,"by":{"0":"43, 46"},"q":[{"src":"brief","b":0,"text":"render[ing] traditionally local criminal conduct a matter for federal enforcement.","cite":"404 U.S. 336, 350"},{"src":"argument","who":"Ms. Blatt","text":"So Sabri is definitely in the context of bribery, and so the question would be if the section -- sorry -- the 1984 version just criminalized gratuities and said for or because of official act 10-year penalty, and you would have to -- that -- there, you would meet, I think, the Spending Clause clear statement and the clear statement under Bass to upset the federal/state balance, and you have a pure Sabri question."}]},{"t":"case","label":"United States v. Brewster","cite":"506 F.2d 62","y":1974,"court":"D.C. Cir.","url":"https://www.courtlistener.com/c/F.2d/506/62/","by":{"0":"22"}},{"t":"case","label":"United States v. Davis","cite":"139 S. Ct. 2319","y":2019,"id":"2018/18-431","sc":1,"by":{"0":"49"},"q":[{"src":"brief","b":0,"text":"ambiguities about the breadth of a criminal statute … in the defendant’s favor.","cite":"139 S. Ct. 2319, 2333"}]},{"t":"case","label":"United States v. Evans","cite":"572 F.2d 455","y":1978,"court":"5th Cir.","url":"https://www.courtlistener.com/c/F.2d/572/455/","by":{"0":"31"},"q":[{"src":"brief","b":0,"text":"some identifiable official act as quid pro quo.","cite":"572 F.2d 455, 481"}]},{"t":"case","label":"United States v. Fernandez","cite":"722 F.3d 1","y":2013,"court":"1st Cir.","url":"https://www.courtlistener.com/c/F.3d/722/1/","by":{"0":"18, 20-21, 33, 37, 50","1":"14, 40","2":"6"},"q":[{"src":"brief","b":0,"text":"accords with the traditional meaning of the term ‘reward’ as something offered to induce another to act favorably on one’s behalf.","cite":"722 F.3d 1, 23"},{"src":"brief","b":0,"text":"clarifies ‘that a bribe can be promised before, but paid after, the official’s action on the payor’s behalf.’","cite":"722 F.3d at 23"}]},{"t":"case","label":"United States v. Gatling","cite":"96 F.3d 1511","y":1996,"court":"D.C. Cir.","url":"https://www.courtlistener.com/c/F.3d/96/1511/","by":{"0":"24"}},{"t":"case","label":"United States v. Hamilton","cite":"46 F.4th 389","y":2022,"court":"5th Cir.","url":"https://www.courtlistener.com/c/F.4th/46/389/","by":{"0":"33, 50","1":"14","2":"19"},"q":[{"src":"opinion","who":"Justice Jackson, dissenting","text":"We gotta stay ahead of [the competition],","cite":"46 F. 4th 389"}]},{"t":"case","label":"United States v. Jennings","cite":"160 F.3d 1006","y":1998,"court":"4th Cir.","url":"https://www.courtlistener.com/c/F.3d/160/1006/","by":{"0":"18, 20"}},{"t":"case","label":"United States v. Johnson","cite":"621 F.2d 1073","y":1980,"court":"10th Cir.","url":"https://www.courtlistener.com/c/F.2d/621/1073/","by":{"0":"24"}},{"t":"case","label":"United States v. Lindberg","cite":"39 F.4th 151","y":2022,"court":"4th Cir.","url":"https://www.courtlistener.com/c/F.4th/39/151/","by":{"0":"38","1":"38"}},{"t":"case","label":"United States v. Santos","cite":"553 U.S. 507","y":2008,"id":"2007/06-1005","sc":1,"by":{"0":"49"},"q":[{"src":"brief","b":0,"text":"mak[e] criminal law in Congress’s stead.","cite":"553 U.S. 507, 514"}]},{"t":"case","label":"United States v. Strand","cite":"574 F.2d 993","y":1978,"court":"9th Cir.","url":"https://www.courtlistener.com/c/F.2d/574/993/","by":{"0":"24"}},{"t":"case","label":"United States v. Sun-Diamond Growers of Cal.","cite":"526 U.S. 398","y":1999,"id":"1998/98-131","sc":1,"by":{"0":"22, 28, 32, 38, 42, 48-49","1":"4, 6, 15, 17, 19, 21, 22, 24, 26, 28, 37, 38","2":"3, 11"},"q":[{"src":"brief","b":0,"text":"a specific intent to give or receive something of value in exchange for an official act.","cite":"526 U.S. at 404"},{"src":"brief","b":1,"text":"for bribery there must be a quid pro quo—a specific intent to give or receive something of value in exchange for an official act. An illegal gratuity, on the other hand, may constitute merely a reward for some future act that the public official will take (and may already have determined to take), or for a past act that he has already taken.","cite":"526 U.S. 398, 404-405"},{"src":"brief","b":1,"text":"linked to a particular ‘official act.’","cite":"526 U.S. at 408"},{"src":"brief","b":2,"text":"a specific intent to give or receive something of value in exchange for an official act.","cite":"526 U.S. at 404"},{"src":"opinion","who":"Opinion of the Court (Justice Kavanaugh)","text":"Whoever otherwise than as provided by law for the proper discharge of offcial duty . . . being a public offcial, former public offcial, or person selected to be a public offcial, otherwise than as provided by law for the proper discharge of offcial duty, directly or indirectly demands, seeks, receives, accepts, or agrees to receive or accept anything of value personally for or because of any offcial act performed or to be performed by such offcial or person . . . shall be fned under this title or imprisoned for not more than two years, or both.","cite":"526 U. S. 398, 404–405"},{"src":"argument","who":"Ms. Blatt","text":"Oh, Sun-Diamond, Justice Scalia goes on and on and on, like his -- one of his favorite cases ever, he just goes on and on about the big difference between a bribery, that's where you pay the money in exchange, and a gratuity, that the action is taken is after the fact. 201 made that distinction."},{"src":"argument","who":"Ms. Sinzdak","text":"I just want to make sure because I do think, for example, in Sun-Diamond, Justice Scalia said that requiring this connection with a particular act is going to eliminate innocuous gift-giving for federal officials --"},{"src":"argument","who":"Ms. Sinzdak","text":"And in -- in -- in Sun-Diamond, this Court said that requiring a tight connection between the reward and specific -- and a specific official acts or, here, you would say specific business or -- business or transactions worth more than $5,000, that was going to eliminate many, many of these cases."}]},{"t":"case","label":"Van Buren v. United States","cite":"141 S. Ct. 1648","y":2021,"id":"2020/19-783","sc":1,"by":{"0":"18, 36"}},{"t":"case","label":"Wooden v. United States","cite":"595 U.S. 360","y":2022,"id":"2021/20-5279","sc":1,"by":{"0":"49"}},{"t":"usc","label":"10 U.S.C. § 924a","url":"https://www.law.cornell.edu/uscode/text/10/924a","by":{"0":"29"}},{"t":"usc","label":"13 U.S.C. § 211","url":"https://www.law.cornell.edu/uscode/text/13/211","by":{"0":"19"},"q":[{"src":"brief","b":0,"text":"with intent to influence such inspector[s] ... to permit or overlook violations","cite":"13 U.S.C. § 211"}]},{"t":"usc","label":"18 U.S.C. § 201","url":"https://www.law.cornell.edu/uscode/text/18/201","subs":["(b)","(b)(1)","(b)(2)","(c)","(c)(1)(A)","(g)(1982)","(g)"],"stext":{"head":"§201. Bribery of public officials and witnesses","paras":[[0,"(a) For the purpose of this section—"],[1,"(1) the term \"public official\" means Member of Congress, Delegate, or Resident Commissioner, either before or after such official has qualified, or an officer or employee or person acting for or on behalf of the United States, or any department, agency or branch of Government thereof, including the District of Columbia, in any official function, under or by authority of any such department, agency, or branch of Government, or a juror;"],[1,"(2) the term \"person who has been selected to be a public official\" means any person who has been nominated or appointed to be a public official, or has been officially informed that such person will be so nominated or appointed; and"],[1,"(3) the term \"official act\" means any decision or action on any question, matter, cause, suit, proceeding or controversy, which may at any time be pending, or which may by law be brought before any public official, in such official's official capacity, or in such official's place of trust or profit."],[0,"(b) Whoever—"],[1,"(1) directly or indirectly, corruptly gives, offers or promises anything of value to any public official or person who has been selected to be a public official, or offers or promises any public official or any person who has been selected to be a public official to give anything of value to any other person or entity, with intent—"],[2,"(A) to influence any official act; or"],[2,"(B) to influence such public official or person who has been selected to be a public official to commit or aid in committing, or collude in, or allow, any fraud, or make opportunity for the commission of any fraud, on the United States; or"],[2,"(C) to induce such public official or such person who has been selected to be a public official to do or omit to do any act in violation of the lawful duty of such official or person;"],[1,"(2) being a public official or person selected to be a public official, directly or indirectly, corruptly demands, seeks, receives, accepts, or agrees to receive or accept anything of value personally or for any other person or entity, in return for:"],[2,"(A) being influenced in the performance of any official act;"],[2,"(B) being influenced to commit or aid in committing, or to collude in, or allow, any fraud, or make opportunity for the commission of any fraud, on the United States; or"],[2,"(C) being induced to do or omit to do any act in violation of the official duty of such official or person;"],[1,"(3) directly or indirectly, corruptly gives, offers, or promises anything of value to any person, or offers or promises such person to give anything of value to any other person or entity, with intent to influence the testimony under oath or affirmation of such first-mentioned person as a witness upon a trial, hearing, or other proceeding, before any court, any committee of either House or both Houses of Congress, or any agency, commission, or officer authorized by the laws of the United States to hear evidence or take testimony, or with intent to influence such person to absent himself therefrom;"],[1,"(4) directly or indirectly, corruptly demands, seeks, receives, accepts, or agrees to receive or accept anything of value personally or for any other person or entity in return for being influenced in testimony under oath or affirmation as a witness upon any such trial, hearing, or other proceeding, or in return for absenting himself therefrom;"],[1,"shall be fined under this title or not more than three times the monetary equivalent of the thing of value, whichever is greater, or imprisoned for not more than fifteen years, or both, and may be disqualified from holding any office of honor, trust, or profit under the United States."],[0,"(c) Whoever—"],[1,"(1) otherwise than as provided by law for the proper discharge of official duty—"],[2,"(A) directly or indirectly gives, offers, or promises anything of value to any public official, former public official, or person selected to be a public official, for or because of any official act performed or to be performed by such public official, former public official, or person selected to be a public official; or"],[2,"(B) being a public official, former public official, or person selected to be a public official, otherwise than as provided by law for the proper discharge of official duty, directly or indirectly demands, seeks, receives, accepts, or agrees to receive or accept anything of value personally for or because of any official act performed or to be performed by such official or person;"],[1,"(2) directly or indirectly, gives, offers, or promises anything of value to any person, for or because of the testimony under oath or affirmation given or to be given by such person as a witness upon a trial, hearing, or other proceeding, before any court, any committee of either House or both Houses of Congress, or any agency, commission, or officer authorized by the laws of the United States to hear evidence or take testimony, or for or because of such person's absence therefrom;"],[1,"(3) directly or indirectly, demands, seeks, receives, accepts, or agrees to receive or accept anything of value personally for or because of the testimony under oath or affirmation given or to be given by such person as a witness upon any such trial, hearing, or other proceeding, or for or because of such person's absence therefrom;"],[1,"shall be fined under this title or imprisoned for not more than two years, or both."],[0,"(d) Paragraphs (3) and (4) of subsection (b) and paragraphs (2) and (3) of subsection (c) shall not be construed to prohibit the payment or receipt of witness fees provided by law, or the payment, by the party upon whose behalf a witness is called and receipt by a witness, of the reasonable cost of travel and subsistence incurred and the reasonable value of time lost in attendance at any such trial, hearing, or proceeding, or in the case of expert witnesses, a reasonable fee for time spent in the preparation of such opinion, and in appearing and testifying."],[0,"(e) The offenses and penalties prescribed in this section are separate from and in addition to those prescribed in sections 1503, 1504, and 1505 of this title."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/18/201?type=usc&year=mostrecent&link-type=html"},"by":{"0":"13-14, 29, 40","1":"6, 7, 14, 16, 17, 26-28, 34, 37, 42, 21, 24, 28, 21, 24, 21, 24, 6, 17, 20, 23, 34, 37, 38, 43, 37, 29, 42, 6, 42, 29, 42, 6","2":"6, 10, 16"},"q":[{"src":"brief","b":0,"text":"in return for … being influenced in the performance of an official act.","cite":"18 U.S.C. § 201(b)(2)(A)"},{"src":"brief","b":1,"text":"for or because of any official act.","cite":"18 U.S.C. 201(c)"},{"src":"brief","b":1,"text":"be considered as a ‘public official’","cite":"18 U.S.C. 201"},{"src":"argument","who":"Ms. Blatt","text":"Under Section 201, there's a 15-year sentence for bribery. Government hates to have to prove a quid pro quo. And there's a two-year sentence for gratuity, where it's really easy to get a water bottle plus a mug and it's over $20."},{"src":"argument","who":"Ms. Sinzdak","text":"We have Congress barring not just bribery but also the -- the acceptance of gratuities without the corruptly mens rea in Section 201. So there's just no reason."}]},{"t":"usc","label":"18 U.S.C. § 666","url":"https://www.law.cornell.edu/uscode/text/18/666","subs":["(a)(1)(A)","(a)","(a)(1)(B)","(a)(2)","(b)","(c)"],"stext":{"head":"§666. Theft or bribery concerning programs receiving Federal funds","paras":[[0,"(a) Whoever, if the circumstance described in subsection (b) of this section exists—"],[1,"(1) being an agent of an organization, or of a State, local, or Indian tribal government, or any agency thereof—"],[2,"(A) embezzles, steals, obtains by fraud, or otherwise without authority knowingly converts to the use of any person other than the rightful owner or intentionally misapplies, property that—"],[3,"(i) is valued at $5,000 or more, and"],[3,"(ii) is owned by, or is under the care, custody, or control of such organization, government, or agency; or"],[2,"(B) corruptly solicits or demands for the benefit of any person, or accepts or agrees to accept, anything of value from any person, intending to be influenced or rewarded in connection with any business, transaction, or series of transactions of such organization, government, or agency involving any thing of value of $5,000 or more; or"],[1,"(2) corruptly gives, offers, or agrees to give anything of value to any person, with intent to influence or reward an agent of an organization or of a State, local or Indian tribal government, or any agency thereof, in connection with any business, transaction, or series of transactions of such organization, government, or agency involving anything of value of $5,000 or more;"],[0,"shall be fined under this title, imprisoned not more than 10 years, or both."],[0,"(b) The circumstance referred to in subsection (a) of this section is that the organization, government, or agency receives, in any one year period, benefits in excess of $10,000 under a Federal program involving a grant, contract, subsidy, loan, guarantee, insurance, or other form of Federal assistance."],[0,"(c) This section does not apply to bona fide salary, wages, fees, or other compensation paid, or expenses paid or reimbursed, in the usual course of business."],[0,"(d) As used in this section—"],[1,"(1) the term \"agent\" means a person authorized to act on behalf of another person or a government and, in the case of an organization or government, includes a servant or employee, and a partner, director, officer, manager, and representative;"],[1,"(2) the term \"government agency\" means a subdivision of the executive, legislative, judicial, or other branch of government, including a department, independent establishment, commission, administration, authority, board, and bureau, and a corporation or other legal entity established, and subject to control, by a government or governments for the execution of a governmental or intergovernmental program;"],[1,"(3) the term \"local\" means of or pertaining to a political subdivision within a State;"],[1,"(4) the term \"State\" includes a State of the United States, the District of Columbia, and any commonwealth, territory, or possession of the United States; and"],[1,"(5) the term \"in any one-year period\" means a continuous period that commences no earlier than twelve months before the commission of the offense or that ends no later than twelve months after the commission of the offense. Such period may include time both before and after the commission of the offense."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/18/666?type=usc&year=mostrecent&link-type=html"},"by":{"0":"5, 21, 26, 48, 5, 36","1":"1, 3, 7, 11, 13-18, 21, 23, 25-33, 35-39, 42, 43, 2, 41, 2, 3, 8, 11, 12, 15, 17, 18, 20, 24, 36-38, 2, 3, 8, 18, 27, 37, 38, 16, 42, 2, 29, 2, 17, 26, 36"},"q":[{"src":"brief","b":0,"text":"Theft or bribery concerning programs receiving federal funds,","cite":"18 U.S.C. § 666"},{"src":"brief","b":0,"text":"benefits in excess of $10,000 under a Federal program.","cite":"18 U.S.C. § 666(b)"},{"src":"brief","b":1,"text":"intending to be influenced or rewarded in connection with","cite":"18 U.S.C. 666(a)(1)(B)"},{"src":"brief","b":1,"text":"anything of value * * * intending to be influenced or rewarded.","cite":"18 U.S.C. 666(a)(1)(B)"},{"src":"argument","who":"Ms. Blatt","text":"Chief Justice, and may it please the Court: Section 666 applies to 19 million state, local, and tribal officials and anyone else whose employer receives federal benefits, including 14 million Medicare-funded healthcare workers."},{"src":"argument","who":"Ms. Blatt","text":"But, if we're going to rely on legislative history, I'll take the footnote in the legislative history of Section 666 itself. When it references the Section 215 statute, it only refers to bribery."},{"src":"argument","who":"Ms. Blatt","text":"The -- the guidelines which were promulgated after Section 666 was passed, but, again, I --"}]},{"t":"usc","label":"19 U.S.C. § 60","url":"https://www.law.cornell.edu/uscode/text/19/60","by":{"0":"30-31"},"q":[{"src":"brief","b":0,"text":"demand[] or receive[] any other or greater fee, compensation, or reward than is allowed by law.","cite":"19 U.S.C. § 60"}]},{"t":"usc","label":"22 U.S.C. § 4202","url":"https://www.law.cornell.edu/uscode/text/22/4202","stext":{"head":"§4202. Exaction of excessive fees for verification of invoices; penalty","paras":[[0,"The fee provided by law for the verification of invoices by consular officers shall, when paid, be held to be a full payment for furnishing blank forms of declaration to be signed by the shipper, and for making, signing, and sealing the certificate of the consular officer thereto; and any consular officer who, under pretense of charging for blank forms, advice, or clerical services in the preparation of such declaration or certificate, charges or receives any fee greater in amount than that provided by law for the verification of invoices, or who demands or receives for any official services, or who allows any clerk or subordinate to receive for any such service, any fee or reward other than the fee provided by law for such service, shall be punishable by imprisonment for not more than one year, or by a fine of not more than $2,000, and shall be removed from his office."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/22/4202?type=usc&year=mostrecent&link-type=html"},"by":{"0":"30-31","1":"20","2":"11"},"q":[{"src":"brief","b":0,"text":"charge[] or receive[] any fee greater in amount than that provided by law.","cite":"22 U.S.C. § 4202"},{"src":"opinion","who":"Justice Jackson, dissenting","text":"receives any fee or reward for his services, except what is allowed to him by law.","cite":"22 U. S. C. § 4202"}]},{"t":"usc","label":"26 U.S.C. § 7212","url":"https://www.law.cornell.edu/uscode/text/26/7212","subs":["(a)"],"by":{"0":"7","1":"3, 11, 20, 26, 25"}},{"t":"usc","label":"28 U.S.C. § 1254","url":"https://www.law.cornell.edu/uscode/text/28/1254","by":{"0":"1"}},{"t":"usc","label":"33 U.S.C. § 447","url":"https://www.law.cornell.edu/uscode/text/33/447","stext":{"head":"§447. Bribery of inspector; penalty","paras":[[0,"Every person who, directly or indirectly, gives any sum of money or other bribe, present, or reward, or makes any offer of the same to any inspector, deputy inspector, or other employee of the office of any supervisor of a harbor with intent to influence such inspector, deputy inspector, or other employee to permit or overlook any violation of the provisions of this subchapter, shall, on conviction thereof, be fined not less than $500 nor more than $1,000, and be imprisoned not less than six months nor more than one year."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/33/447?type=usc&year=mostrecent&link-type=html"},"by":{"0":"19, 33","1":"23"},"q":[{"src":"brief","b":0,"text":"it conspicuously does not make it illegal simply to grant a benefit.","cite":"33 U.S.C. § 447"}]},{"t":"law","label":"Pub. L. No. 99-646","url":"https://www.govinfo.gov/link/statute/100/3592","by":{"0":"34"}},{"t":"reg","label":"2 C.F.R. § 200.318","url":"https://www.ecfr.gov/current/title-2/section-200.318","by":{"0":"47"},"q":[{"src":"brief","b":0,"text":"gratuities, favors, or anything of monetary value from contractors or parties to subcontracts.","cite":"2 C.F.R. § 200.318(c)(1)"}]},{"t":"reg","label":"5 C.F.R. § 2635.201","url":"https://www.ecfr.gov/current/title-5/section-2635.201","by":{"0":"39"}},{"t":"reg","label":"20 C.F.R. § 10.703","url":"https://www.ecfr.gov/current/title-20/section-10.703","by":{"0":"30"}},{"t":"reg","label":"52 Fed. Reg. 46046","url":"https://www.govinfo.gov/link/fr/52/46046","by":{"0":"41","1":"31"}},{"t":"const","label":"Article III, Section 24","by":{"0":"45"}},{"t":"usc","label":"18 U.S.C. § 600","url":"https://www.law.cornell.edu/uscode/text/18/600","stext":{"head":"§600. Promise of employment or other benefit for political activity","paras":[[0,"Whoever, directly or indirectly, promises any employment, position, compensation, contract, appointment, or other benefit, provided for or made possible in whole or in part by any Act of Congress, or any special consideration in obtaining any such benefit, to any person as consideration, favor, or reward for any political activity or for the support of or opposition to any candidate or any political party in connection with any general or special election to any political office, or in connection with any primary election or political convention or caucus held to select candidates for any political office, shall be fined under this title or imprisoned not more than one year, or both."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/18/600?type=usc&year=mostrecent&link-type=html"},"by":{"0":"19","1":"22, 23"},"q":[{"src":"brief","b":0,"text":"the only way § 600 might be violated … is if people were promised employment or special consideration for employment … as an enticement or reward for future political activity.","cite":"18 U.S.C. § 600"}]},{"t":"case","label":"Burton v. United States","cite":"202 U.S. 344","y":1906,"id":"scdb/1905-122","sc":1,"by":{"1":"6"}},{"t":"case","label":"Clark v. Martinez","cite":"543 U.S. 371","y":2005,"id":"2004/03-878","sc":1,"by":{"1":"32, 33"},"q":[{"src":"brief","b":1,"text":"comes into play only when, after the application of ordinary textual analysis, the statute is found to be susceptible of more than one construction.","cite":"543 U.S. 371, 385"}]},{"t":"case","label":"Dixson v. United States","cite":"465 U.S. 482","y":1984,"id":"1983/82-5279","sc":1,"by":{"1":"6"},"q":[{"src":"brief","b":1,"text":"the first federal bribery statute of general application","cite":"465 U.S. 482, 491 n.8"},{"src":"brief","b":1,"text":"effort to reformulate and rationalize all federal criminal statutes dealing with the integrity of government.","cite":"465 U.S. at 492"}]},{"t":"case","label":"Duncan v. Walker","cite":"533 U.S. 167","y":2001,"id":"2000/00-121","sc":1,"by":{"1":"22"},"q":[{"src":"brief","b":1,"text":"It is ‘a cardinal principle of statutory construction’ that ‘a statute ought, upon the whole, to be so construed that, if it can be prevented, no clause, sentence, or word shall be superfluous, void, or insignificant.’","cite":"533 U.S. 167, 174"}]},{"t":"case","label":"Evans v. United States","cite":"504 U.S. 255","y":1992,"id":"1991/90-6105","sc":1,"by":{"1":"33"}},{"t":"case","label":"Greer v. United States","cite":"593 U.S. 503","y":2021,"id":"2020/19-8709","sc":1,"by":{"1":"43"}},{"t":"case","label":"Jennings v. Rodriguez","cite":"583 U.S. 281","y":2018,"id":"2017/15-1204","sc":1,"by":{"1":"33"}},{"t":"case","label":"Lorillard v. Pons","cite":"434 U.S. 575","y":1978,"id":"1977/76-1346","sc":1,"by":{"1":"31"},"q":[{"src":"brief","b":1,"text":"Congress is presumed to be aware of an administrative or judicial interpretation of a statute and to adopt that interpretation when it re-enacts a statute without change,","cite":"434 U.S. 575, 580"}]},{"t":"case","label":"Mason v. Muncaster","cite":"16 F. Cas. 1052","y":1828,"court":"C.C.D.D.C.","url":"https://www.courtlistener.com/c/F.%20Cas./16/1052/","by":{"1":"4"}},{"t":"case","label":"National Ass’n of Mfrs. v. Department of Def.","cite":"583 U.S. 109","y":2018,"id":"2017/16-299","sc":1,"by":{"1":"18"},"q":[{"src":"brief","b":1,"text":"‘begins with the statutory text, and ends there as well.’","cite":"583 U.S. 109, 127"}]},{"t":"case","label":"Neder v. United States","cite":"527 U.S. 1","y":1999,"id":"1998/97-1985","sc":1,"by":{"1":"43"}},{"t":"case","label":"Northcross v. Board of Educ.","cite":"412 U.S. 427","y":1973,"id":"1972/72-1164","sc":1,"by":{"1":"31"}},{"t":"case","label":"Ocasio v. United States","cite":"578 U.S. 282","y":2016,"id":"2015/14-361","sc":1,"by":{"1":"35"},"q":[{"src":"brief","b":1,"text":"only when a criminal statute contains a ‘grievous ambiguity or uncertainty,’ and ‘only if, after seizing everything from which aid can be derived,’ the Court ‘can make no more than a guess as to what Congress intended.’","cite":"578 U.S. 282, 295 n.8"}]},{"t":"case","label":"Smith v. City of Jackson","cite":"544 U.S. 228","y":2005,"id":"2004/03-1160","sc":1,"by":{"1":"31"},"q":[{"src":"brief","b":1,"text":"when Congress uses the same language in two statutes having similar purposes, particularly when one is enacted shortly after the other, it is appropriate to presume that Congress intended that text to have the same meaning in both statutes.","cite":"544 U.S. 228, 233"}]},{"t":"case","label":"Sorich v. United States","cite":"555 U.S. 1204","y":2009,"url":"https://supreme.justia.com/cases/federal/us/555/1204/","sc":1,"by":{"1":"17, 18, 35","2":"4"},"q":[{"src":"brief","b":1,"text":"bribes and gratuities to public officials.","cite":"555 U.S. 1204, 1207"}]},{"t":"case","label":"State v. Brown","cite":"267 S.W.2d 682","y":1954,"court":"Mo.","url":"https://www.courtlistener.com/c/S.W.2d/267/682/","by":{"1":"6"}},{"t":"case","label":"TRW Inc. v. Andrews","cite":"534 U.S. 19","y":2001,"id":"2001/00-1045","sc":1,"by":{"1":"22"}},{"t":"case","label":"Taggart v. Lorenzen","cite":"139 S. Ct. 1795","y":2019,"id":"2018/18-489","sc":1,"by":{"1":"28"}},{"t":"case","label":"United States v. Ganim","cite":"510 F.3d 134","y":2007,"court":"2d Cir.","url":"https://www.courtlistener.com/c/F.3d/510/134/","by":{"1":"21","2":"5"},"q":[{"src":"brief","b":1,"text":"‘to ‘reward’ connotes an illegal gratuity.","cite":"510 F.3d 134, 150"}]},{"t":"case","label":"United States v. Hansen","cite":"599 U.S. 762","y":2023,"id":"2022/22-179","sc":1,"by":{"1":"34, 40"},"q":[{"src":"brief","b":1,"text":"the statute prohibits a substantial amount of protected speech’ relative to its ‘plainly legitimate sweep,’","cite":"599 U.S. 762, 770"}]},{"t":"case","label":"United States v. Hawkins","cite":"777 F.3d 880","y":2015,"court":"7th Cir.","url":"https://www.courtlistener.com/c/F.3d/777/880/","by":{"1":"11, 14","2":"23, 23"},"q":[{"src":"brief","b":1,"text":"[m]any other circuits have taken the same position.","cite":"777 F.3d at 881"}]},{"t":"case","label":"United States v. Johnson","cite":"874 F.3d 990","y":2017,"court":"7th Cir.","url":"https://www.courtlistener.com/c/F.3d/874/990/","by":{"1":"11","2":"23"}},{"t":"case","label":"United States ex rel. Schutte v. SuperValu Inc.","cite":"598 U.S. 739","y":2023,"id":"2022/21-1326","sc":1,"by":{"1":"35"},"q":[{"src":"brief","b":1,"text":"policy arguments * * * ‘cannot supersede the clear statutory text.’","cite":"598 U.S. 739, 758"}]},{"t":"case","label":"United States v. Terry","cite":"707 F.3d 607","y":2013,"court":"6th Cir.","url":"https://www.courtlistener.com/c/F.3d/707/607/","by":{"1":"33"},"q":[{"src":"brief","b":1,"text":"because a contribution has a legitimate alternative explanation: The donor supports the candidate’s election for all manner of possible reasons.","cite":"707 F.3d 607, 613"}]},{"t":"const","label":"Article II, Section 1, Clause 7","text":"The President shall, at stated Times, receive for his Services, a Compensation, which shall neither be encreased nor diminished during the Period for which he shall have been elected, and he shall not receive within that Period any other Emolument from the United States, or any of them.","by":{"1":"4","2":"11"}},{"t":"const","label":"Amendment I","clauses":[["establishment","Establishment Clause"],["free-exercise","Free Exercise Clause"],["free-speech","Free Speech Clause"],["free-press","Free Press Clause"],["assembly-petition","Assembly, Petition and Association"]],"text":"Congress shall make no law respecting an establishment of religion, or prohibiting the free exercise thereof; or abridging the freedom of speech, or of the press; or the right of the people peaceably to assemble, and to petition the Government for a redress of grievances.","by":{"1":"16, 33, 34"}},{"t":"law","label":"Pub. L. No. 87-849","url":"https://www.govinfo.gov/link/statute/76/1119","by":{"1":"6","2":"12"}},{"t":"law","label":"Pub. L. No. 99-370","url":"https://www.govinfo.gov/link/statute/100/779","by":{"1":"30, 31","2":"13"}},{"t":"law","label":"Pub. L. No. 98-473","url":"https://www.govinfo.gov/link/statute/98/2143","by":{"1":"7, 28"}},{"t":"law","label":"Pub. L. No. 101-647","url":"https://www.govinfo.gov/link/statute/104/4789","by":{"1":"42"}},{"t":"law","label":"Pub. L. No. 96-646","url":"https://www.govinfo.gov/link/statute/100/3592","by":{"1":"7, 8, 29"}},{"t":"law","label":"Pub. L. No. 101-73","url":"https://www.govinfo.gov/link/statute/103/499","by":{"1":"31"}},{"t":"usc","label":"18 U.S.C. § 206","url":"https://www.law.cornell.edu/uscode/text/18/206","subs":["(1958)"],"by":{"1":"42"}},{"t":"usc","label":"18 U.S.C. § 207","url":"https://www.law.cornell.edu/uscode/text/18/207","subs":["(1958)"],"by":{"1":"42"}},{"t":"usc","label":"18 U.S.C. § 215","url":"https://www.law.cornell.edu/uscode/text/18/215","subs":["(a)","(a)(2)","(d)"],"stext":{"head":"§215. Receipt of commissions or gifts for procuring loans","paras":[[0,"(a) Whoever—"],[1,"(1) corruptly gives, offers, or promises anything of value to any person, with intent to influence or reward an officer, director, employee, agent, or attorney of a financial institution in connection with any business or transaction of such institution; or"],[1,"(2) as an officer, director, employee, agent, or attorney of a financial institution, corruptly solicits or demands for the benefit of any person, or corruptly accepts or agrees to accept, anything of value from any person, intending to be influenced or rewarded in connection with any business or transaction of such institution;"],[0,"shall be fined not more than $1,000,000 or three times the value of the thing given, offered, promised, solicited, demanded, accepted, or agreed to be accepted, whichever is greater, or imprisoned not more than 30 years, or both, but if the value of the thing given, offered, promised, solicited, demanded, accepted, or agreed to be accepted does not exceed $1,000, shall be fined under this title or imprisoned not more than one year, or both."],[0,"[(b) Transferred]"],[0,"(c) This section shall not apply to bona fide salary, wages, fees, or other compensation paid, or expenses paid or reimbursed, in the usual course of business."],[0,"(d) Federal agencies with responsibility for regulating a financial institution shall jointly establish such guidelines as are appropriate to assist an officer, director, employee, agent, or attorney of a financial institution to comply with this section. Such agencies shall make such guidelines available to the public."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/18/215?type=usc&year=mostrecent&link-type=html"},"by":{"1":"16, 27, 29-31, 42, 31, 29, 31, 42, 31"},"q":[{"src":"brief","b":1,"text":"corruptly accept[ing] or agree[ing] to accept[] anything of value from any person, intending to be influenced or rewarded in connection with any business or transaction of","cite":"18 U.S.C. 215(a)(2)"},{"src":"brief","b":1,"text":"intending to be influenced or rewarded,","cite":"18 U.S.C. 215(a)(2)"},{"src":"argument","who":"Ms. Blatt","text":"Let me take on Section -- Section 215. So, you're -- you're right, the -- the -- the wording is quite identical, and the only court to address the issue has held 215 is a bribery statute."},{"src":"argument","who":"Ms. Blatt","text":"But the only court -- no court has held that Section 215 applies to gratuities. It's got a 30-year sentence. And even if you did think it did, I would say the title at least mentions gifts."}]},{"t":"usc","label":"18 U.S.C. § 1346","url":"https://www.law.cornell.edu/uscode/text/18/1346","by":{"1":"34"}},{"t":"usc","label":"18 U.S.C. § 1422","url":"https://www.law.cornell.edu/uscode/text/18/1422","by":{"1":"42","2":"12"}},{"t":"usc","label":"18 U.S.C. § 1503","url":"https://www.law.cornell.edu/uscode/text/18/1503","subs":["(a)"],"by":{"1":"25"}},{"t":"usc","label":"18 U.S.C. § 1505","url":"https://www.law.cornell.edu/uscode/text/18/1505","by":{"1":"25"}},{"t":"usc","label":"18 U.S.C. § 1912","url":"https://www.law.cornell.edu/uscode/text/18/1912","by":{"1":"20"}},{"t":"usc","label":"18 U.S.C. § 3553","url":"https://www.law.cornell.edu/uscode/text/18/3553","subs":["(a)(6)"],"by":{"1":"43"}},{"t":"usc","label":"26 U.S.C. § 7214","url":"https://www.law.cornell.edu/uscode/text/26/7214","subs":["(a)"],"by":{"1":"42","2":"11-12"}},{"t":"reg","label":"52 Fed. Reg. 43,939","url":"https://www.govinfo.gov/link/fr/52/43939","by":{"1":"31"}},{"t":"case","label":"Blockburger v. United States","cite":"284 U.S. 299","y":1932,"id":"scdb/1931-120","sc":1,"by":{"2":"7"}},{"t":"case","label":"Rewis v. United States","cite":"401 U.S. 808","y":1971,"id":"1970/5342","sc":1,"by":{"2":"23"}},{"t":"case","label":"United States v. Bonito","cite":"57 F.3d 167","y":1995,"court":"2d Cir.","url":"https://www.courtlistener.com/c/F.3d/57/167/","by":{"2":"5"}},{"t":"case","label":"United States v. Boyland","cite":"862 F.3d 279","y":2017,"court":"2d Cir.","url":"https://www.courtlistener.com/c/F.3d/862/279/","by":{"2":"16"},"q":[{"src":"brief","b":2,"text":"section [666] is more expansive than § 201,","cite":"862 F.3d 279, 291"}]},{"t":"case","label":"United States v. Ford","cite":"435 F.3d 204","y":2006,"court":"2d Cir.","url":"https://www.courtlistener.com/c/F.3d/435/204/","by":{"2":"6, 22"},"q":[{"src":"brief","b":2,"text":"Section 201 lacks an explicit intent requirement as to recipients of alleged bribes while Section 666 contains one.","cite":"435 F.3d 204, 210 n.2"}]},{"t":"case","label":"United States v. Kaufman","cite":"2023 WL 1871669","y":2023,"court":"2d Cir. Feb. 10","by":{"2":"13"}},{"t":"case","label":"United States v. Lonich","cite":"23 F.4th 881","y":2022,"court":"9th Cir.","url":"https://www.courtlistener.com/c/F.4th/23/881/","by":{"2":"13"}},{"t":"case","label":"United States v. O’Brien","cite":"560 U.S. 218","y":2010,"id":"2009/08-1569","sc":1,"by":{"2":"7"}},{"t":"case","label":"United States v. Roberson","cite":"998 F.3d 1237","y":2021,"court":"11th Cir.","url":"https://www.courtlistener.com/c/F.3d/998/1237/","by":{"2":"16"},"q":[{"src":"brief","b":2,"text":"not import[] an ‘official act’ requirement,","cite":"998 F.3d 1237, 1247"}]},{"t":"case","label":"United States v. Robinson","cite":"663 F.3d 265","y":2011,"court":"7th Cir.","url":"https://www.courtlistener.com/c/F.3d/663/265/","by":{"2":"17"}},{"t":"case","label":"United States v. Rodrigues","cite":"159 F.3d 439","y":1998,"court":"9th Cir.","url":"https://www.courtlistener.com/c/F.3d/159/439/","by":{"2":"13"}},{"t":"const","label":"Article I, Section 9, Clause 8","clauses":[["emoluments","Emoluments Clauses"]],"text":"No Title of Nobility shall be granted by the United States: And no Person holding any Office of Profit or Trust under them, shall, without the Consent of the Congress, accept of any present, Emolument, Office, or Title, of any kind whatever, from any King, Prince, or foreign State.","by":{"2":"11"}},{"t":"reg","label":"5 C.F.R. § 2635.204","url":"https://www.ecfr.gov/current/title-5/section-2635.204","by":{"2":"9"}},{"t":"case","label":"Other Authorities—continued: U.S. Brief, United States v. Grace","cite":"568 F. App’x 344","y":2014,"court":"5th Cir.","url":"https://www.courtlistener.com/c/F.%20App%E2%80%99x/568/344/","by":{"2":"22"}},{"t":"case","label":"U.S. Brief, United States v. McGee","cite":"612 F.3d 627","y":2010,"court":"7th Cir.","url":"https://www.courtlistener.com/c/F.3d/612/627/","by":{"2":"23"}},{"t":"case","label":"U.S. Brief, United States v. Velazquez-Corchado","cite":"2014 WL 2994358","by":{"2":"23"}}]};